head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > createSubmission]<br/>Submission 을 동적으로 생성합니다. 동일 ID 의 Submission 이 이미 존재하는 경우 기존 Submission 을 삭제 후 재생성합니다.",
    "validation" : [
        "submissionInfo(필수) 파라미터로 생성할 Submission 의 속성을 JSON 객체로 설정할 수 있어야 합니다.",
        "submissionInfo.id(필수) 로 Submission 의 ID 를 설정할 수 있어야 합니다.",
        "submissionInfo.ref(선택) 로 서버로 보낼 요청(Request) 데이터가 위치할 DataCollection 의 조건 표현식을 지정할 수 있어야 합니다.",
        "submissionInfo.target(선택) 으로 서버로부터 받은 응답(Response) 데이터를 반영할 DataCollection 의 조건 표현식을 지정할 수 있어야 합니다.",
        "submissionInfo.method / mediatype / encoding(선택) 으로 HTTP Method, 데이터 타입, 서버 인코딩 타입을 설정할 수 있어야 합니다.",
        "submissionInfo.processMsg(선택) 와 hideProcessMsg(선택) 로 통신 중 표시할 프로세스 메시지를 설정할 수 있어야 합니다.",
        "submissionInfo.submitDoneHandler(선택) 는 응답 Status 가 정상인 경우 호출되고, submitErrorHandler(선택) 는 오류 응답(200 미만 또는 300 이상) 인 경우 호출되어야 합니다.",
        "submissionInfo.timeout(선택) 과 submitTimeoutHandler(선택) 를 설정하면 설정 시간 경과 시 submitTimeoutHandler 가 호출되어야 합니다.",
        "submissionInfo.abortTrigger(선택) 를 true 로 설정하면 processMsg 에 취소 버튼이 노출되어야 하며, singleMode(선택) 를 true 로 설정하면 동일 Submission 이 실행 중일 때 중복 호출이 무시되어야 합니다.",
        "동일 ID 의 Submission 이 이미 존재하면 기존 Submission 을 삭제 후 재생성해야 합니다.",
        "submissionInfo.submitHandler(선택) 함수가 false 를 반환하면 Submission 요청이 취소되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// submitHandler false 반환 여부 플래그 (시나리오 5 에서 사용)
scwin.cancelRequest = false;

// 공통 submitHandler
scwin.exam_submitHandler = function (e) {
    if (scwin.cancelRequest === true) {
        return false;
    }
    return true;
};

// 공통 submitTimeoutHandler
scwin.exam_submitTimeoutHandler = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("submitTimeoutHandler: Timeout 발생");
    $p.hideProcessMessage();
};



scwin.btn_createSubmission_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.cancelRequest = false;

    // 이전 시나리오에서 남아있을 수 있는 Process Message 정리
    $p.hideProcessMessage();

    // 매 시나리오 실행 시 이전 데이터 제거
    dlt_userList.removeAll();

    if (scenario === "1") {
        // 시나리오 1 : 예시 1 기반 - 기본 동적 생성 (ref/target/method/mediatype/encoding/processMsg/handler)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 기본 동적 생성 (예시 1) ──");

        // ref 로 전달할 요청 데이터 설정 (DataMap)
        dma_search.set("keyword", "test");

        // append 동작 확인용 초기 데이터 1건 (응답 7건 + 초기 1건 = 최종 8건)
        dlt_userList.insertRow(0);
        dlt_userList.setCellData(0, "id", "000");
        dlt_userList.setCellData(0, "name", "초기데이터");
        dlt_userList.setCellData(0, "age", "99");
        dlt_userList.setCellData(0, "dept", "사전등록");

        var submissionInfo = {
            "id" : "submission_dynamic",
            "ref" : 'data:json,[{"id":"dma_search"}]',
            "target" : 'data:json,[{"id":"dlt_userList","action":"append"}]',
            "action" : "/data/p_createSubmission_userList.json",
            "method" : "post",
            "mediatype" : "application/json",
            "encoding" : "UTF-8",
            "processMsg" : "Loading...",
            "hideProcessMsg" : false,
            "submitDoneHandler" : function (e) {
                console.log(e.responseStatusCode);
                var rowCount = dlt_userList.getRowCount();
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler: responseStatusCode=" + e.responseStatusCode);
                wf_body_bottom.getObj("scwin").setReturnValue("로드된 행 수 (append 후): " + rowCount);
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                console.log(e.errorType);
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("submission_dynamic");
    } else if (scenario === "2") {
        // 시나리오 2 : 동일 ID 재생성 (spec) - 재생성된 Submission 이 새 URL 로 실제 동작하는지 검증
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 동일 ID 재생성 ──");

        // 1차 생성 : 존재하지 않는 URL 로 Submission 생성
        var info1 = {
            "id" : "sbm_dynamic",
            "action" : "/data/p_createSubmission_not_exist.json",
            "method" : "post",
            "mediatype" : "application/json"
        };
        $p.createSubmission(info1);
        wf_body_bottom.getObj("scwin").setReturnValue("재생성 전 action : '" + $p.getSubmission("sbm_dynamic").action + "'");

        // 2차 생성 : 같은 ID 로 재생성 (정상 URL + target 설정)
        var info2 = {
            "id" : "sbm_dynamic",
            "action" : "/data/p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitDoneHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("재생성된 Submission 실행 결과: 로드된 행 수 = " + dlt_userList.getRowCount());
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(info2);
        wf_body_bottom.getObj("scwin").setReturnValue("재생성 후 action : '" + $p.getSubmission("sbm_dynamic").action + "'");

        // 재생성된 Submission 실행 → 새 action URL 로 데이터 로드
        $p.executeSubmission("sbm_dynamic");
    } else if (scenario === "3") {
        // 시나리오 3 : submitErrorHandler 호출 (서버 오류 - 404)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : submitErrorHandler 호출 (서버 오류) ──");
        var submissionInfo = {
            "id" : "sbm_dynamic",
            "action" : "/data/p_createSubmission_not_exist.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitDoneHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler: responseStatusCode=" + e.responseStatusCode);
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                console.log(e.errorType);
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler: errorType=" + e.errorType + " (" + e.responseStatusCode + ")");
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_dynamic");
    } else if (scenario === "4") {
        // 시나리오 4 : 예시 2 기반 - Timeout + abortTrigger + singleMode
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : Timeout + abortTrigger + singleMode (예시 2) ──");
        var submissionInfo2 = {
            "id" : "submission_timeout",
            "action" : "http://10.255.255.1/timeout_test.json",
            "method" : "post",
            "mediatype" : "application/json",
            "timeout" : 50,
            "processMsg" : "Processing...",
            "hideProcessMsg" : false,
            "abortTrigger" : true,
            "singleMode" : true,
            "submitTimeoutHandler" : scwin.exam_submitTimeoutHandler
        };
        $p.createSubmission(submissionInfo2);

        // singleMode 검증 : 연속 2회 호출 시 두번째 호출은 무시됨
        var firstCall = $p.executeSubmission("submission_timeout");
        var secondCall = $p.executeSubmission("submission_timeout");
        wf_body_bottom.getObj("scwin").setReturnValue("singleMode: 1차 호출 결과=" + firstCall + ", 2차 호출 무시됨(결과=" + secondCall + ")");
    } else if (scenario === "5") {
        // 시나리오 5 : submitHandler false 반환으로 요청 취소
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : submitHandler false 반환으로 요청 취소 ──");
        scwin.cancelRequest = true;
        var submissionInfo = {
            "id" : "sbm_dynamic",
            "action" : "/data/p_createSubmission_userList.json",
            "target" : 'data:json,[{"id":"dlt_userList"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitHandler" : scwin.exam_submitHandler,
            "submitDoneHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler 호출됨 (취소 실패)");
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_dynamic");

        // 일정 시간 후 데이터 미로드 확인 (통신 취소 시 dlt_userList 그대로 유지)
        $p.setTimeout(function () {
            var rowCount = dlt_userList.getRowCount();
            wf_body_bottom.getObj("scwin").setReturnValue("submitHandler false → 취소됨");
            wf_body_bottom.getObj("scwin").setReturnValue("dlt_userList.getRowCount() : " + rowCount);
        }, "chk_cancel", 500);
    }
};
